-- PDCA Compliance · /dashboard/ehs/prestadores (aud8 86/95) · RD-95: "?" nas colunas e na busca.
-- ADITIVA: só textos de ajuda novos (erp_ajuda_campo). Não cria/altera tabela, RLS, policy, grant ou dado de cliente.
-- Idempotente (ON CONFLICT (chave) DO NOTHING).
INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
SELECT v.chave, v.grupo, v.rotulo, v.o_que, v.para_que, v.exemplo, v.erro, v.ordem, v.rota, 'compliance', 'publicado'
FROM (VALUES
 ('compliance.prestadores.busca', 'Prestadores PJ/MEI', 'Buscar', 'Digite parte da razão social, do CNPJ ou do nome fantasia para filtrar os prestadores.', 'Encontra rápido um prestador numa lista grande sem rolar a tabela toda.', 'Digitar "transporte" para achar a transportadora contratada.', 'Esperar que a busca traga prestadores de outra empresa: a lista só mostra os da sua carteira.', 1, '/dashboard/ehs/prestadores'),
 ('compliance.prestadores.razao_social', 'Prestadores PJ/MEI', 'Razão Social', 'Nada a preencher: o nome jurídico (razão social) do prestador PJ ou MEI contratado.', 'Identifica a empresa prestadora nos documentos, contratos e na matriz de EHS.', 'Prestador "Alfa Manutenção Industrial LTDA".', 'Confundir razão social com nome fantasia: a busca aceita os dois, mas a coluna mostra a razão social.', 2, '/dashboard/ehs/prestadores'),
 ('compliance.prestadores.cnpj', 'Prestadores PJ/MEI', 'CNPJ', 'Nada a preencher: o CNPJ do prestador.', 'É a chave única do prestador; evita duplicar a mesma empresa e liga aos documentos fiscais.', 'CNPJ 12.345.678/0001-90.', 'Cadastrar o mesmo prestador duas vezes com CNPJ digitado diferente.', 3, '/dashboard/ehs/prestadores'),
 ('compliance.prestadores.tipo', 'Prestadores PJ/MEI', 'Tipo', 'Nada a preencher: o enquadramento do prestador (MEI, PJ Simples, PJ Lucro Real, Prestação de serviço).', 'Orienta as exigências fiscais e de documentação de cada prestador.', 'Tipo "PJ Simples" para uma empresa do Simples Nacional.', 'Deixar o tipo em branco: sem ele a classificação do prestador fica incompleta.', 4, '/dashboard/ehs/prestadores'),
 ('compliance.prestadores.empresa', 'Prestadores PJ/MEI', 'Empresa', 'Nada a preencher: mostra a qual empresa do grupo o prestador está vinculado.', 'Quando você vê mais de uma empresa, separa os prestadores de cada carteira.', 'Prestador vinculado à "Construtora Alfa".', 'Lançar o prestador na empresa errada ao cadastrar.', 5, '/dashboard/ehs/prestadores'),
 ('compliance.prestadores.responsavel', 'Prestadores PJ/MEI', 'Responsável', 'Nada a preencher: o nome do responsável/contato do prestador.', 'É com quem a sua empresa fala sobre o contrato, documentos e pendências de EHS.', 'Responsável "João Silva" do prestador Alfa.', 'Deixar sem responsável: dificulta cobrar ASO e documentos em dia.', 6, '/dashboard/ehs/prestadores'),
 ('compliance.prestadores.valor_mensal', 'Prestadores PJ/MEI', 'Valor mensal', 'Nada a preencher: o valor do contrato mensal com o prestador (quando informado).', 'Dá a referência de custo do prestador para acompanhamento e rateio.', 'Valor mensal R$ 3.500,00.', 'Supor que o valor mensal cobre serviços avulsos: ele é o contrato recorrente, não extras.', 7, '/dashboard/ehs/prestadores'),
 ('compliance.prestadores.ehs', 'Prestadores PJ/MEI', 'EHS', 'Nada a preencher: indicador de saúde e segurança do prestador (situação de ASO e documentos de EHS).', 'Mostra de relance se o prestador está com os documentos de segurança (ASO, treinamentos) em dia antes de liberar o trabalho.', 'Indicador verde = ASO e documentos de EHS do prestador em dia.', 'Liberar prestador com EHS pendente: trabalhar sem ASO/documentos expõe a empresa em fiscalização.', 8, '/dashboard/ehs/prestadores'),
 ('compliance.prestadores.acoes', 'Prestadores PJ/MEI', 'Ações', 'Nada a preencher: os botões para abrir, editar ou gerir o prestador.', 'Leva aos detalhes do prestador (documentos, EHS) e à edição do cadastro.', 'Abrir o prestador para anexar o ASO do responsável técnico.', 'Procurar as ações numa coluna errada: elas ficam na última coluna da linha.', 9, '/dashboard/ehs/prestadores')
) AS v(chave, grupo, rotulo, o_que, para_que, exemplo, erro, ordem, rota)
WHERE EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'erp_ajuda_campo')
ON CONFLICT (chave) DO NOTHING;
